j2:if.g2:evaluate:
var translatedText = new GlideRecord("sys_translated_text");
translatedText.addQuery("documentkey", jelly.jvar_assessable_type);
translatedText.addQuery("language", jelly.jvar_lang_obj.value);
translatedText.query();
if (!translatedText.hasNext()) {
	countValidLang = countValidLang - 1;
	jelly.jvar_lang_obj.valid = false;
} else 
	jelly.jvar_lang_obj.valid = true;

j:jelly.script:
function changeSessionLanguage(targetLanguageValue, instanceID, sessionLanguageValue) {
	if (targetLanguageValue == sessionLanguageValue)
		return;


	if (window.location.href.indexOf("sysparm_lang") !== -1) {
		var index = window.location.href.indexOf("sysparm_lang");
		window.location.href = window.location.href.replaceAt(index, "sysparm_lang=" + targetLanguageValue);
	} else {
		window.location.href +=  "$[AMP]sysparm_lang=" + targetLanguageValue + "$[AMP]sysparm_assessable_sysid=" + instanceID;
	}
}

String.prototype.replaceAt = function(index, replacement) {
	return this.substr(0, index) + replacement+ this.substr(index + replacement.length);
}

